using UnityEngine;using UnityEngine.InputSystem;
public class WoodlandEquipment:MonoBehaviour {
 public WoodlandPlayer player;public WoodlandInventory inventory;public WoodlandFieldKitUI kit;public Transform radio,handTorch;public Light handheldBeam;public AudioClip radioStatic;
 public string held="rifle";string next="rifle",supply;float transition=1,actionTime,actionLength,bob;bool switched;AudioSource radioAudio;
 public bool ActionBusy=>actionTime>0;public string ActiveSupply=>supply;public float SupplyProgress=>actionLength>0?1-actionTime/actionLength:0;public void CancelSupply(){actionTime=0;supply=null;}public bool HandsBusy=>held!="rifle"||transition<1||ActionBusy;
 public string ActionLabel=>ActionBusy?"Working… "+Mathf.RoundToInt((1-actionTime/actionLength)*100)+"%":"";
 void Start(){radioAudio=gameObject.AddComponent<AudioSource>();radioAudio.spatialBlend=0;radioAudio.playOnAwake=false;radioAudio.volume=.3f;held="rifle";if(player.visorEffects){var e=inventory.Find("ear_defenders");player.visorEffects.earDefenders=e!=null&&e.attachment=="ears";}}
 public bool Equip(string item){string kind=item=="handtorch"?"torch":item;if(inventory.Find(kind)==null||ActionBusy||player.IsReloading||(player.nodeRepair&&player.nodeRepair.Busy)||(player.visorEffects&&player.visorEffects.Busy)||inventory.anatomy.Incapacitated)return false;next=item;transition=0;switched=false;return true;}
 public bool UseSupply(string kind){if(ActionBusy||player.IsReloading||inventory.Find(kind)==null||inventory.anatomy.Incapacitated||(kind=="medical"&&!inventory.anatomy.NeedsBandage))return false;if(kind!="filter"&&kind!="torch_cell"&&kind!="medical"&&kind!="splint"&&kind!="suit_patch"){inventory.Use(kind);return false;}supply=kind;actionLength=kind=="suit_patch"?3.2f:kind=="splint"?3.5f:kind=="medical"?3f:1.8f;actionTime=actionLength;return true;}
 void Update(){if(WoodlandDemoControls.Paused)return;float dt=Time.deltaTime;transition=Mathf.Min(1,transition+dt/ .65f);if(!switched&&transition>=.4f){held=next;inventory.data.equipped=held;switched=true;}if(ActionBusy){actionTime=Mathf.Max(0,actionTime-dt);if(inventory.anatomy.Dead){actionTime=0;supply=null;}else if(actionTime==0){inventory.Use(supply);supply=null;}kit.Refresh();}var k=Keyboard.current;if(k==null||kit.Busy||Cursor.lockState!=CursorLockMode.Locked||inventory.anatomy.Incapacitated)return;if(k.digit1Key.wasPressedThisFrame)Equip("rifle");if(k.digit2Key.wasPressedThisFrame)Equip("radio");if(k.digit3Key.wasPressedThisFrame)Equip("handtorch");if(k.rKey.wasPressedThisFrame&&held=="handtorch")UseSupply("torch_cell");if(k.eKey.wasPressedThisFrame&&held=="radio")Transmit();if(held=="radio"){var item=inventory.Find("radio");item.battery=Mathf.Max(0,item.battery-dt*.015f);}if(held=="handtorch"&&handheldBeam&&handheldBeam.enabled)player.battery=Mathf.Max(0,player.battery-dt*.05f);}
 public bool Transmit(){var item=inventory.Find("radio");if(item==null||item.battery<1||!radioAudio||radioAudio.isPlaying)return false;item.battery-=1;bool linked=player.serviced&&Vector3.Distance(player.transform.position,player.sensor.position)<150;inventory.Notify(linked?"Relay 04 linked — location report transmitted.":"No relay link — broken signal. Repair relay 04.");if(radioStatic)radioAudio.PlayOneShot(radioStatic,.6f);return linked;}
 void LateUpdate(){bool available=!player.cinematicLocked&&!kit.Busy&&!(player.nodeRepair&&player.nodeRepair.Busy)&&!(player.visorEffects&&player.visorEffects.Busy)&&!inventory.anatomy.Incapacitated;bool radioVisible=available&&held=="radio",torchVisible=available&&held=="handtorch";if(radio)radio.gameObject.SetActive(radioVisible);if(handTorch)handTorch.gameObject.SetActive(torchVisible);if(handheldBeam){handheldBeam.enabled=torchVisible&&player.battery>0;bool focus=Mouse.current!=null&&Mouse.current.rightButton.isPressed;handheldBeam.spotAngle=Mathf.Lerp(handheldBeam.spotAngle,focus?24:49,1-Mathf.Exp(-Time.deltaTime*9));handheldBeam.color=new Color(1,.95f,.85f);handheldBeam.range=30;handheldBeam.intensity=focus?10:7;}if(HandsBusy&&available){player.rifle.gameObject.SetActive(false);if(player.adsRifle)player.adsRifle.gameObject.SetActive(false);if(player.focusRifle)player.focusRifle.gameObject.SetActive(false);player.watch.gameObject.SetActive(false);}float lower=transition<.4f?Mathf.SmoothStep(0,1,transition/.4f):1-Mathf.SmoothStep(0,1,(transition-.4f)/.6f);bob+=Time.deltaTime;Pose(radio,lower,true);Pose(handTorch,lower,false);}
 void Pose(Transform t,float lower,bool isRadio){if(!t)return;t.localPosition=new Vector3(isRadio?-.19f:.2f,-.09f-lower*.4f+Mathf.Sin(bob*1.9f)*.002f,.48f);t.localRotation=Quaternion.Euler(lower*24,isRadio?192:172,Mathf.Sin(bob*1.2f)*.6f);}
}
